package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.outbox;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.moderation_trust_service.application.port.ModerationOutboxPort;
@Component public class JpaModerationOutboxAdapter implements ModerationOutboxPort{private final ModerationOutboxRepository repo;private final ObjectMapper mapper;public JpaModerationOutboxAdapter(ModerationOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String type,String aggregateType,String aggregateId,String actor,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Map<String,Object>e=new LinkedHashMap<>();e.put("eventId",id);e.put("eventType",type);e.put("eventVersion",1);e.put("occurredAt",Instant.now());e.put("producer","moderation-trust-service");e.put("aggregateType",aggregateType);e.put("aggregateId",aggregateId);e.put("correlationId",correlation==null?id.toString():correlation);e.put("actorId",actor);e.put("payload",payload);var row=new ModerationOutboxEvent();row.setId(id);row.setAggregateId(aggregateId);row.setEventType(type);row.setOccurredAt(Instant.now());row.setPayload(mapper.writeValueAsString(e));repo.save(row);}catch(Exception e){throw new IllegalStateException("Cannot create moderation outbox event",e);}}}
